INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Netzplan ein wichtiges Werkzeug im Projektmanagement?', 2, '[{"text": "Ja", "correct": true, "because": "Darstellt zeitliche Abfolge"}, {"text": "Nein", "correct": false, "because": "Es ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt der Netzplan?', 3, '[{"text": "Zeitliche Abhängigkeiten visualisieren", "correct": true, "because": "Fördert Planung"}, {"text": "Team direkt motivieren", "correct": false, "because": "Nebenaspekt"}, {"text": "Kosten sofort festlegen", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Netzplan zeigt Aktivitäten und Abhängigkeiten. b) Er wird nur im Abschluss genutzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Planung entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente enthält ein Netzplan?', 4, '[{"text": "Aktivitäten", "correct": true, "because": "Darstellen Aufgaben"}, {"text": "Unklare Schritte", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Abhängigkeiten", "correct": true, "because": "Zeigen Reihenfolge"}, {"text": "Knotenpunkte", "correct": true, "because": "Verbinden Aktivitäten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Netzplan geplant werden?', 2, '[{"text": "Ja", "correct": true, "because": "Alternative Methoden möglich"}, {"text": "Nein", "correct": false, "because": "Werkzeug optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode nutzt der Netzplan häufig?', 3, '[{"text": "CPM (Critical Path Method)", "correct": true, "because": "Bestimmt kritischen Pfad"}, {"text": "Keine Analyse", "correct": false, "because": "Fehlt Struktur"}, {"text": "Zufällige Reihenfolge", "correct": false, "because": "Unsystematisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Netzplan nur für große Projekte geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Netzplan in der Planung?', 3, '[{"text": "Zeitliche Steuerung ermöglichen", "correct": true, "because": "Visualisiert Ablauf"}, {"text": "Team direkt einteilen", "correct": false, "because": "Durchführungsaspekt"}, {"text": "Kosten direkt überwachen", "correct": false, "because": "Controlling-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Netzplan identifiziert den kritischen Pfad. b) Er zeigt nur Arbeitspakete.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Netzplan?', 3, '[{"text": "Zeitliche Abhängigkeiten unklar", "correct": true, "because": "Fehlende Struktur"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Ineffizienz möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Netzplan ohne Zeitangaben erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Zeit ist Kernbestandteil"}, {"text": "Ja", "correct": false, "because": "Unvollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt einen Netzplan-Eintrag?', 3, '[{"text": "A -> B (3 Tage)", "correct": true, "because": "Aktivität mit Abhängigkeit"}, {"text": "Irgendwas machen", "correct": false, "because": "Zu vage"}, {"text": "Team soll starten", "correct": false, "because": "Keine Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Netzplan nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Team braucht Zeitablauf"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein Netzplan?', 4, '[{"text": "Aktivitäten", "correct": true, "because": "Darstellen Aufgaben"}, {"text": "Unklare Reihenfolge", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Pfeile für Abhängigkeiten", "correct": true, "because": "Zeigen Zusammenhänge"}, {"text": "Dauerangaben", "correct": true, "because": "Definieren Zeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der Netzplan dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt den Netzplan?', 3, '[{"text": "Software wie MS Project", "correct": true, "because": "Erstellt Netzpläne"}, {"text": "Keine Software", "correct": false, "because": "Fehlt Struktur"}, {"text": "Spontane Skizzen", "correct": false, "because": "Unübersichtlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Netzplan ohne Arbeitspakete erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Aufgabenbasis fehlt"}, {"text": "Ja", "correct": false, "because": "Unvollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Erstellung eines Netzplans?', 3, '[{"text": "Unklare Abhängigkeiten", "correct": true, "because": "Verhindern Struktur"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Erstellung"}, {"text": "Gute Dokumentation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Netzplan hilft beim Zeitmanagement. b) Er ist nur für IT-Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen des Netzplans?', 3, '[{"text": "Kritischer Pfad erkennbar", "correct": true, "because": "Fördert Zeitsteuerung"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Abhängigkeiten", "correct": false, "because": "Fördert Struktur"}]');
